const fs = require('fs');
const path = require('path');
const dir = 'g:/0.LMS/V2-HeSinhThai/hos/Docs';
const files = ['LoTrinh-Bootstrap5-UI.data.js','LoTrinh-Bootstrap5-UI.detail.js','LoTrinh-Bootstrap5-UI.app.js'];
const out = path.join(dir, 'LoTrinh-Bootstrap5-UI.js');
const header = '/* CMS L\u1ed9 tr\u00ecnh Bootstrap 5 \u2014 ECO LMS (data + detail + app) */\n';
const parts = files.map(f => {
  const p = path.join(dir, f);
  if (!fs.existsSync(p)) { console.error('missing', f); process.exit(1); }
  return fs.readFileSync(p, 'utf8');
});
fs.writeFileSync(out, header + parts.join('\n'), 'utf8');
console.log('merged', fs.statSync(out).size);
"

node -e "
const fs = require('fs');
const dir = 'g:/0.LMS/V2-HeSinhThai/hos/Docs';
const htmlPath = dir + '/LoTrinh-Bootstrap5-UI.html';
const jsPath = dir + '/LoTrinh-Bootstrap5-UI.js';
let html = fs.readFileSync(htmlPath, 'utf8');
let js = fs.readFileSync(jsPath, 'utf8');
js = js.replace(/<\/script>/gi, '<\\/script>');
const marker = '<script src=\"LoTrinh-Bootstrap5-UI.js\"></script>';
if (html.indexOf(marker) === -1) { console.error('marker not found'); process.exit(1); }
html = html.replace(marker, '<script>\n' + js + '\n</script>');
fs.writeFileSync(htmlPath, html, 'utf8');
fs.unlinkSync(jsPath);
console.log('done', fs.statSync(htmlPath).size);
"

input.contents:
var fs = require("fs");
var dir = __dirname;
var htmlPath = dir + "/LoTrinh-Bootstrap5-UI.html";
var jsPath = dir + "/LoTrinh-Bootstrap5-UI.js";
var html = fs.readFileSync(htmlPath, "utf8");
var js = fs.readFileSync(jsPath, "utf8");
var marker = '<script src="LoTrinh-Bootstrap5-UI.js"></script>';
if (html.indexOf(marker) === -1) {
  console.error("marker not found");
  process.exit(1);
}
html = html.replace(marker, "<script>\n" + js + "\n</script>");
fs.writeFileSync(htmlPath, html, "utf8");
fs.unlinkSync(jsPath);
console.log("merged", fs.statSync(htmlPath).size);
